import React, { useEffect, useState } from "react";
import { makeApiRequest } from "../axiosService/ApiCall";
import DataTable from "react-data-table-component";
import { FaEye, FaEdit } from "react-icons/fa";
import { Button, Modal, Form, Spinner } from "react-bootstrap";
import { useFormik } from "formik";
import * as yup from "yup";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "../../src/App.css";
import { encryptData, decryptData } from "../Auth/SecurityCrypto";
import axios from "axios";

const Spotpair = () => {
  const [pairData, setPairData] = useState([]);
  const [pairDetails, setPairDetails] = useState([]);
  const [loading, setLoading] = useState(true);
  const [show, setShow] = useState(false);
  const [id, setId] = useState();
  const handleClose = () => setShow(false);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [editpairList, setEditpairList] = useState(0);
  // console.log("editpairList", editpairList);
  const [adminType, setAdminType] = useState("");
  const editpairListres = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const editpairListres = await makeApiRequest(params);
      // console.log("editpairListres", editpairListres);
      if (editpairListres.status) {
        const response = editpairListres.data;
        // console.log("response--", response);
        setEditpairList(response?.adminPermissions?.pairList?.Edit);
        setAdminType(response?.admin_type);
      }
    } catch (error) {
      console.log("err--", error);
      // toast(setEditpairList.message);
      // toast("Something Went Wrong...");
    }
  };
  useEffect(() => {
    editpairListres();
  }, []);

  const handleShow = async (id) => {
    try {
      setShow(true);
      setId(id);
      let params = {
        url: `onespotpair/${id}`,
        method: "GET",
      };
      let response = await makeApiRequest(params);
      if (response.status === true) {
        const userList = response.data;
        setPairDetails(userList);
      } else {
        setPairDetails({});
      }
    } catch (error) {
      console.log("error", error);
    } finally {
      setLoading(false);
    }
  };
  const getPairList = async () => {
    try {
      let params = {
        url: `spotpair`,
        method: "GET",
      };
      let response = await makeApiRequest(params);
      // console.log("response", response);
      if (response.status === true) {
        const userList = response.data;
        setPairData(userList);
        setHistoryLoading(false);
      } else {
        setPairData([]);
        setHistoryLoading(false);
      }
    } catch (error) {
      console.log("error", error);
      setHistoryLoading(false);
    } finally {
      setLoading(false);
      setHistoryLoading(false);
    }
  };
  const {
    touched,
    errors,
    values,
    handleBlur,
    handleChange,
    handleSubmit,
    resetForm,
    setValues,
  } = useFormik({
    initialValues: {
      symbol: "",
      name: "",
      minimumTradeTotal: "",
      makerFee: "",
      takerFee: "",
      withdrawFee: "",
      swapFee: "",
      MinimumAmount: "",
    },
    validationSchema: yup.object().shape({
      symbol: yup.string().required(),
      name: yup.string().required(),
      minimumTradeTotal: yup.number().required(),
      makerFee: yup.number().required(),
      takerFee: yup.number().required(),
      withdrawFee: yup.number().required(),
      swapFee: yup.number().required(),
      MinimumAmount: yup
        .number()
        .required('Minimum amount is required')
        .when('symbol', {
          is: (symbol) => 
            symbol == 'ADAUSDT'
          ,
          then: (schema) => schema.min(1, 'Kindly set the minimum withdrawal amount to 1 or above.'),
        }),
    }),
    onSubmit: async (values) => {
      // console.log("values", values);
      setShow(true);
      values.id = id;
      let params = {
        url: `updatespotpair`,
        method: "POST",
        data: values,
      };
      let pairdecryptRes = await makeApiRequest(params);
      // console.log("pairupdate", pairdecryptRes);

      if (pairdecryptRes.data) {
        const pairdecryptedResponse = decryptData(pairdecryptRes.data);
        // console.log("pairdecryptedResponse", pairdecryptedResponse);

        if (pairdecryptedResponse.status == true) {
          getPairList();
          setShow(false);
          toast.success(pairdecryptedResponse.message, {
            position: "top-right",
          });
          resetForm();
          setPairDetails({});
        } else {
          getPairList();
          setShow(false);
          resetForm();
          toast.error(pairdecryptedResponse.data, {
            position: "top-right",
          });
        }
      }
    },
  });
  useEffect(() => {
    getPairList();
  }, []);

  const setTheValue = async () => {
    try {
      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;
      Object.values(pairDetails).map((data) => {
        setValues({
          id: data.id,
          name: data.name,
          symbol: data.symbol,
          minimumTradeTotal: data.minimumTradeTotal,
          makerFee: data.makerFee,
          takerFee: data.takerFee,
          withdrawFee: data.withdrawFee,
          swapFee: data.swapFee,
          MinimumAmount: data.withdrawMinimumAmount,
          ip: lastloginIpAddress
        });
      });
    } catch (error) {
      console.log(error)
    }
  }

  useEffect(() => {
    setTheValue()
  }, [pairDetails]);
  const columnsDeposit = [
    {
      name: "S.No",
      selector: (row, index) => index + 1,
      sortable: true,
      width: "100px",
    },
    {
      name: "Symbol",
      selector: (row) =>
        row.symbol == "USDT"
          ? row.symbol
          : `${row.symbol.substring(0, 3)} / ${row.symbol.substring(3, 7)}`,
      sortable: true,
      width: "240px",
    },
    {
      name: "Pair Name",
      selector: (row) => row.name,
      sortable: true,
    },
    {
      name: "Edit",
      selector: (row) => (
        <FaEdit
          style={{ cursor: "pointer" }}
          onClick={() => handleShow(row._id)}
          className="copy-icon"
        />
      ),
    },
  ];
  const customSort = (rows, selector, direction) => {
    return rows.sort((a, b) => {
      if (typeof selector(a) === "string") {
        const aField = selector(a).toLowerCase();
        const bField = selector(b).toLowerCase();

        let comparison = 0;

        if (aField > bField) {
          comparison = 1;
        } else if (aField < bField) {
          comparison = -1;
        }
        return direction === "desc" ? comparison * -1 : comparison;
      } else {
        const aField = selector(a).props.children
          ? parseFloat(selector(a).props.children)
          : 0;
        const bField = selector(b).props.children
          ? parseFloat(selector(b).props.children)
          : 0;
        let comparison = 0;

        if (aField > bField) {
          comparison = 1;
        } else if (aField < bField) {
          comparison = -1;
        }
        return direction === "desc" ? comparison * -1 : comparison;
      }
    });
  };

  return (
    <div className="App">
      <ToastContainer />
      <div className="container-fluid">
        <div className=" text-dark">
          <div className="row">
            <div className="col-sm-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user  ms-lg-0">Pair List</h3>
              </div>
              <div className="custom-inside-saled-order text-center mt-0">
                <h4>Spot Pair List</h4> <br />
                <div className="liquidity-table-1">
                  <DataTable
                    columns={columnsDeposit}
                    data={pairData}
                    pagination
                    persistTableHead
                    sortFunction={customSort}
                    paginationPerPage={10}
                    paginationRowsPerPageOptions={[10, 20, 30]}
                    progressPending={historyLoading}
                    progressComponent={
                      <div className="text center py-4 w-100">
                        <Spinner animation="border" />
                      </div>
                    }
                    noDataComponent={<div className="text-center">No Data</div>}
                  />
                </div>
              </div>
            </div>
          </div>
          <Modal
            show={show}
            onHide={() => (handleClose(), resetForm())}
            centered
          >
            <Modal.Header closeButton>
              {" "}
              {values.symbol === "USDT" ? "Token Details" : "Pair Details"}
            </Modal.Header>
            <Modal.Body>
              <Form onSubmit={handleSubmit}>
                <Form.Group
                  className="mb-3"
                  controlId="exampleForm.ControlInput1"
                >
                  <Form.Label>
                    {values.symbol === "USDT" ? "Token Symbol" : "Pair Symbol"}
                  </Form.Label>
                  <Form.Control
                    type="text"
                    name="symbol"
                    value={
                      values.symbol == "USDT"
                        ? values.symbol
                        : `${values.symbol.substring(
                          0,
                          3
                        )} / ${values.symbol.substring(3, 7)}`
                    }
                    onChange={handleChange}
                    placeholder="name@example.com"
                    disabled
                  />
                </Form.Group>
                <Form.Group
                  className="mb-3"
                  controlId="exampleForm.ControlInput1"
                >
                  <Form.Label>
                    {values.symbol === "USDT" ? "Token Name" : "Pair Name"}
                  </Form.Label>
                  <Form.Control
                    type="text"
                    name="name"
                    value={values.name}
                    onChange={handleChange}
                    placeholder="name@example.com"
                    disabled
                  />
                </Form.Group>
                {values.symbol !== "USDT" && (
                  <>
                    <Form.Group
                      className="mb-3"
                      controlId="exampleForm.ControlInput1"
                    >
                      <Form.Label>Minimum Trade Total</Form.Label>
                      <Form.Control
                        type="number"
                        name="minimumTradeTotal"
                        value={values.minimumTradeTotal}
                        disabled={editpairList == 0 && adminType == "SubAdmin"}
                        onChange={handleChange}
                        placeholder="minimum trade total"
                      />
                      {touched.minimumTradeTotal &&
                        errors.minimumTradeTotal && (
                          <p className="text-danger">
                            {errors.minimumTradeTotal}
                          </p>
                        )}
                    </Form.Group>
                    <Form.Group
                      className="mb-3"
                      controlId="exampleForm.ControlInput1"
                    >
                      <Form.Label>Maker Fee %</Form.Label>
                      <Form.Control
                        type="number"
                        name="makerFee"
                        value={values.makerFee}
                        disabled={editpairList == 0 && adminType == "SubAdmin"}
                        onChange={handleChange}
                        placeholder="maker fee"
                      />
                      {touched.makerFee && errors.makerFee && (
                        <p className="text-danger">{errors.makerFee}</p>
                      )}
                    </Form.Group>
                    <Form.Group
                      className="mb-3"
                      controlId="exampleForm.ControlInput1"
                    >
                      <Form.Label>Taker Fee %</Form.Label>
                      <Form.Control
                        type="number"
                        name="takerFee"
                        value={values.takerFee}
                        disabled={editpairList !== 1 && adminType == "SubAdmin"}
                        onChange={handleChange}
                        placeholder="taker fee"
                      />
                      {touched.takerFee && errors.takerFee && (
                        <p className="text-danger">{errors.takerFee}</p>
                      )}
                    </Form.Group>
                  </>
                )}
                <Form.Group
                  className="mb-3"
                  controlId="exampleForm.ControlInput1"
                >
                  <Form.Label>Withdraw Fee %</Form.Label>
                  <Form.Control
                    type="number"
                    name="withdrawFee"
                    value={values.withdrawFee}
                    disabled={editpairList !== 1 && adminType == "SubAdmin"}
                    onChange={handleChange}
                    placeholder="withdraw fee"
                  />
                  {touched.withdrawFee && errors.withdrawFee && (
                    <p className="text-danger">{errors.withdrawFee}</p>
                  )}
                </Form.Group>
                <Form.Group
                  className="mb-3"
                  controlId="exampleForm.ControlInput1"
                >
                  <Form.Label>Swap Fee %</Form.Label>
                  <Form.Control
                    type="number"
                    name="swapFee"
                    value={values.swapFee}
                    disabled={editpairList !== 1 && adminType == "SubAdmin"}
                    onChange={handleChange}
                    placeholder="swap fee"
                  />
                  {touched.swapFee && errors.swapFee && (
                    <p className="text-danger">{errors.swapFee}</p>
                  )}
                </Form.Group>
                <Form.Group
                  className="mb-3"
                  controlId="exampleForm.ControlInput1"
                >
                  <Form.Label>Withdraw Minimum Amount</Form.Label>
                  <Form.Control
                    type="number"
                    name="MinimumAmount"
                    value={values.MinimumAmount}
                    disabled={editpairList !== 1 && adminType == "SubAdmin"}
                    onChange={handleChange}
                    placeholder="withdraw minimum amount"
                  />
                  {touched.MinimumAmount && errors.MinimumAmount && (
                    <p className="text-danger">{errors.MinimumAmount}</p>
                  )}
                </Form.Group>
                <div className="d-flex justify-content-end">
                  <Button
                    type="submit"
                    disabled={editpairList !== 1 && adminType == "SubAdmin"}
                    className="custom-nav-button-1 active"
                  >
                    Update pair
                  </Button>
                </div>
              </Form>
            </Modal.Body>
          </Modal>
        </div>
      </div>
    </div>
  );
};

export default Spotpair;
